with metrics as (select *, lag(budget) over w_part prev_budget, lead(budget) over w_part next_budget, row_number() over w_part event_seq from departments where dept_name = 'Engineering' window w_part as (partition by location order by budget, id)) select case when next_budget >= 4277000 then 'LARGE' else 'SMALL' end as next_budget_tier, location, stddev_samp(budget) as budget_stddev, size(collect_set(dept_name)) as num_dept_names, approx_percentile(next_budget, array(0.25, 0.5, 0.75)) as next_budget_quartiles, sort_array(collect_set(location)) as location_list, grouping_id() as gid from metrics group by grouping sets ((case when next_budget >= 4277000 then 'LARGE' else 'SMALL' end, location), (case when next_budget >= 4277000 then 'LARGE' else 'SMALL' end), ());
